const $ = (selector) => document.querySelector(selector);
const api = async (path, options = {}) => { if(path==="/knowledge/evaluation/run"&&evaluationSettings){const body=JSON.parse(options.body||"{}"); Object.assign(body,evaluationSettings); options={...options,body:JSON.stringify(body)};} const response=await fetch(path,{headers:{"Content-Type":"application/json",...(options.headers||{})},...options}); if(!response.ok){const body=await response.json().catch(()=>({detail:"Request failed"}));throw new Error(body.detail||"Request failed")} const result=await response.json(); if(path==="/knowledge/documents/metadata"){toast(`${result.updated.length} document${result.updated.length===1?"":"s"} updated${result.errors.length?`; ${result.errors.length} failed`:""}`);} if(path==="/knowledge/evaluation/run"){lastEvaluationReport=result; let gate=$("#quality-gate"); if(!gate){gate=document.createElement("div");gate.id="quality-gate";$("#quality-summary").before(gate);} gate.className=`quality-gate ${result.quality_passed?"pass":"fail"}`; gate.innerHTML=`${result.quality_passed?"✓ Quality thresholds passed":"! Quality thresholds need review"}${result.quality_issues.length?`<small>${result.quality_issues.map(escapeHtml).join(" · ")}</small>`:""}`;} return result; };
const toast = (message) => { const node=$("#toast"); node.textContent=message; node.classList.add("show"); setTimeout(()=>node.classList.remove("show"),2800); };
const escapeHtml = (value) => String(value).replace(/[&<>\"']/g,(character)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[character]));
const MINIMUM_RESPONSE_LOADER_MS = 900;
const waitForMinimumLoaderTime = async (startedAt) => { const remaining=MINIMUM_RESPONSE_LOADER_MS-(performance.now()-startedAt); if(remaining>0) await new Promise((resolve)=>setTimeout(resolve,remaining)); };
let answerAnimationToken=0;
let sourcePreviews=[];
let lastEvaluationReport=null;
let evaluationSettings=null;
const animateAnswer = (answer) => { const token=++answerAnimationToken; const node=$("#answer"); node.textContent=""; const duration=Math.min(3200,Math.max(900,answer.length*11)); const startedAt=performance.now(); const reveal=()=>{if(token!==answerAnimationToken)return; const progress=Math.min(1,(performance.now()-startedAt)/duration); node.textContent=answer.slice(0,Math.ceil(progress*answer.length)); if(progress<1) requestAnimationFrame(reveal);}; requestAnimationFrame(reveal); };
const setAnswerLoading = (loading) => { $("#result-section").classList.remove("hidden"); $("#answer-loader").classList.toggle("hidden",!loading); $("#answer-content").classList.toggle("hidden",loading); if(loading){answerAnimationToken+=1;$("#result-meta").textContent="Analysing your documents...";$("#source-count").textContent="";$("#sources").innerHTML="";} };
const renderConfidenceWarning = (result) => { let warning=$("#confidence-warning"); if(!warning){warning=document.createElement("div");warning.id="confidence-warning";$(".answer-card").before(warning);} warning.className=`confidence-warning ${result.confidence_warning?"":"hidden"}`; warning.textContent=result.confidence_warning_message||""; };
const renderLatencyWarning = (result) => { let warning=$("#latency-warning"); if(!warning){warning=document.createElement("div");warning.id="latency-warning";warning.className="latency-warning";$(".answer-card").before(warning);} warning.className=`latency-warning ${result.latency_warning?"":"hidden"}`; warning.textContent=result.latency_warning_message||""; };
const renderRetrievalDiagnostics = (result) => { let node=$("#retrieval-diagnostics"); if(!node){node=document.createElement("div");node.id="retrieval-diagnostics";node.className="retrieval-diagnostics";$(".answer-card").after(node);} const d=result.retrieval_diagnostics||{}; node.innerHTML=`<span>Retrieval diagnostics</span><strong>${escapeHtml(d.search_mode||"hybrid")}</strong><span>· ${Number(d.top_k||5)} sources</span><span>· ${escapeHtml(d.file_type||"all")}</span><code>${escapeHtml(d.query||"")}</code>`; };
const renderAgentTrace = (result) => { let node=$("#agent-trace"); if(!node){node=document.createElement("details");node.id="agent-trace";node.className="agent-trace";$("#retrieval-diagnostics").after(node);} node.innerHTML=`<summary>View agent trace</summary><div class="trace-list">${(result.agent_trace||[]).map((item)=>`<div class="trace-step"><span class="trace-dot ${item.status}"></span><strong>${escapeHtml(item.stage)}</strong><span>${escapeHtml(item.detail||item.status)}</span></div>`).join("")}</div>`; };
let conversationId=null;
let lastStaleDocumentCount=null;
let sourceDocuments=[];
let previewDocumentName=null;
let previewPage=1;
let previewTotalPages=1;
const ask = async (question) => { if(!question.trim()) return; const startedAt=performance.now(); const button=document.querySelector("#ask-form .primary-button"); button.disabled=true; button.querySelector("span").textContent="Thinking..."; setAnswerLoading(true); try { const payload={query:question,top_k:Number($("#retrieval-count-select")?.value||5),confidence_threshold:Number($("#confidence-mode")?.value||0.4),search_mode:$("#search-mode")?.value||"hybrid",latency_profile:$("#latency-profile")?.value||"balanced"}; const fileType=$("#ask-file-type")?.value||"all"; if(fileType!=="all") payload.file_type=fileType; if(conversationId) payload.conversation_id=conversationId; const result=await api("/knowledge/ask",{method:"POST",body:JSON.stringify(payload)}); conversationId=result.conversation_id; await waitForMinimumLoaderTime(startedAt); renderResult(result); renderConfidenceWarning(result); renderLatencyWarning(result); renderRetrievalDiagnostics(result); renderAgentTrace(result); await loadConversations(); } catch(error){setAnswerLoading(false);toast(error.message)} finally {button.disabled=false;button.querySelector("span").textContent="Ask Atlas";} };
const openCitationPreview = (index) => { const citation=sourcePreviews[index]; if(!citation)return; if(citation.page_number&&citation.source_name.toLowerCase().endsWith(".pdf")){openDocumentPreview(citation.source_name,citation.page_number);return;} openSourcePreview(index); };
const renderResult = (result) => { setAnswerLoading(false); animateAnswer(result.answer); sourcePreviews=result.citations; $("#result-meta").textContent=`${result.verified?"Verified":"Needs review"} · ${result.duration_ms} ms · ${result.attempts} attempt${result.attempts===1?"":"s"}`; $("#source-count").textContent=`${result.citations.length} source${result.citations.length===1?"":"s"}`; $("#sources").innerHTML=result.citations.length?result.citations.map((c,index)=>{const confidence=Math.round(c.confidence*100);const strength=confidence>=70?"Strong":confidence>=40?"Moderate":"Low";return `<article class="source-card"><div class="source-card-heading"><strong>[${c.citation_id}] ${escapeHtml(c.source_name)}</strong><span class="source-tag">${c.page_number?`page ${c.page_number}`:"document"}</span></div><div class="citation-confidence"><span>${strength} match</span><strong>${confidence}%</strong><i style="width:${confidence}%"></i></div><div class="citation-signals"><span>Semantic ${Math.round(c.semantic_score*100)}%</span><span>Keywords ${Math.round(c.lexical_score*100)}%</span></div><p class="source-excerpt">${escapeHtml(c.excerpt)}</p><p class="source-location">Chunk: ${escapeHtml(c.chunk_id)}</p><button class="preview-button" type="button" data-preview-index="${index}">${c.page_number&&c.source_name.toLowerCase().endsWith(".pdf")?`Open PDF page ${c.page_number} ↗`:"View source excerpt ↗"}</button></article>`;}).join(""):"<div class=\"empty-state\">No supporting sources were found.</div>"; document.querySelectorAll(".preview-button").forEach((button)=>button.addEventListener("click",()=>openCitationPreview(Number(button.dataset.previewIndex)))); $("#result-section").scrollIntoView({behavior:"smooth",block:"start"}); };
const openSourcePreview = (index) => { const citation=sourcePreviews[index]; if(!citation)return; $("#preview-title").textContent=`[${citation.citation_id}] ${citation.source_name}`; $("#preview-meta").textContent=`${citation.page_number?`Page ${citation.page_number}`:"Document"} · ${citation.chunk_id}`; $("#preview-text").textContent=citation.excerpt; $("#source-preview").showModal(); };
const loadHealth = async (notify=true) => { try { const health=await api("/knowledge/documents/health"); const label=health.status==="ready"?"Knowledge base ready":health.status==="empty"?"No documents indexed":"Re-indexing recommended"; $("#knowledge-health").innerHTML=`<div class="health-status ${health.status}"><span class="health-dot"></span><strong>${label}</strong><span>${health.document_count} documents · ${health.indexed_document_count} indexed · ${health.chunk_count} chunks${health.stale_document_count?` · ${health.stale_document_count} stale`:""}</span></div>`; if(notify&&lastStaleDocumentCount!==null&&health.stale_document_count>lastStaleDocumentCount) toast(`${health.stale_document_count} document${health.stale_document_count===1?"":"s"} changed — re-index recommended`); lastStaleDocumentCount=health.stale_document_count; } catch(error){toast(error.message)} };
const loadProviderHealth = async () => { try { const health=await api("/knowledge/providers/health"); let node=$("#provider-health"); if(!node){node=document.createElement("div");node.id="provider-health";node.className="provider-health";$("#knowledge-health").after(node);} const indexLabel=health.index_status==="needs_reindex"?" · Re-index required":health.index_status==="compatible"?" · Index compatible":" · Index not created"; node.innerHTML=`<span class="health-dot ${health.status}"></span><strong>${health.status==="ready"?"Providers ready":"Provider attention needed"}</strong><span>${escapeHtml(health.detail)}</span><small>${escapeHtml(health.llm_provider)} · ${escapeHtml(health.llm_model)} · ${escapeHtml(health.embedding_provider)} · ${escapeHtml(health.embedding_model)}${indexLabel}</small>`; } catch(error){toast(error.message)} };
const loadIngestionActivity = async () => { try { const events=await api("/knowledge/documents/activity"); $("#ingestion-activity").innerHTML=events.length?events.slice(0,8).map((event)=>`<div class="activity-row"><span class="activity-action ${event.action}">${escapeHtml(event.action)}</span><span class="activity-document">${escapeHtml(event.document_name)}</span><span class="activity-detail">${escapeHtml(event.detail)}</span><time>${new Date(`${event.created_at}Z`).toLocaleString()}</time></div>`).join(""):'<span class="muted">No activity yet.</span>'; } catch(error){toast(error.message)} };
const renderSources = () => { const query=$("#source-filter").value.toLowerCase().trim(); const type=$("#type-filter").value; const sort=$("#source-sort").value; const documents=sourceDocuments.filter((document)=>document.name.toLowerCase().includes(query)&&(type==="all"||document.file_type===type)).sort((left,right)=>{if(sort==="newest"||sort==="oldest"){const direction=sort==="newest"?-1:1; return direction*String(left.upload_date||"").localeCompare(String(right.upload_date||""));} if(sort==="largest"||sort==="smallest"){return (sort==="largest"?-1:1)*(left.size_bytes-right.size_bytes);} return left.name.localeCompare(right.name);}); $("#source-list").innerHTML=documents.length?documents.map(d=>`<div class="source-row"><div class="source-main"><span class="source-name">▤ &nbsp;${escapeHtml(d.name)}</span><span class="document-status ${d.status}">${d.status}</span></div><span class="source-actions"><span>${Math.round(d.size_bytes/1024)} KB · ${escapeHtml(d.file_type)} · ${d.upload_date?new Date(`${d.upload_date}Z`).toLocaleDateString():"—"}</span><button class="source-preview-action" type="button" data-document-name="${escapeHtml(d.name)}" title="Preview document" aria-label="Preview ${escapeHtml(d.name)}">⌕</button><a class="source-download" href="/knowledge/documents/${encodeURIComponent(d.name)}/download" title="Download document" aria-label="Download ${escapeHtml(d.name)}">↓</a><button class="source-reindex" type="button" data-document-path="${escapeHtml(d.path)}" title="Re-index document" aria-label="Re-index ${escapeHtml(d.name)}">↻</button><button class="source-delete" type="button" data-document-name="${escapeHtml(d.name)}" title="Delete document" aria-label="Delete ${escapeHtml(d.name)}">×</button></span></div>`).join(""):'<div class="empty-state">No matching documents.</div>'; document.querySelectorAll(".source-preview-action").forEach((button)=>button.addEventListener("click",()=>openDocumentPreview(button.dataset.documentName))); document.querySelectorAll(".source-reindex").forEach((button)=>button.addEventListener("click",()=>reindexDocument(button.dataset.documentPath,button))); document.querySelectorAll(".source-delete").forEach((button)=>button.addEventListener("click",()=>deleteDocument(button.dataset.documentName))); };
const openDocumentPreview = async (name,page=1) => { try { previewDocumentName=name; previewPage=page; const response=await fetch(`/knowledge/documents/${encodeURIComponent(name)}/preview?page=${page}`); if(!response.ok){const body=await response.json().catch(()=>({detail:"Preview unavailable"}));throw new Error(body.detail||"Preview unavailable");} previewTotalPages=Number(response.headers.get("X-Preview-Total-Pages")||1); const isPdf=name.toLowerCase().endsWith(".pdf"); $("#preview-title").textContent=name; $("#preview-meta").textContent=isPdf?`Original PDF · Page ${page}`:"Original uploaded document"; $("#preview-text").textContent=await response.text(); $("#pdf-navigation").classList.toggle("hidden",!isPdf); if(isPdf){$("#pdf-page").value=page;$("#pdf-page").max=previewTotalPages;$("#pdf-total").textContent=`of ${previewTotalPages}`;$("#pdf-prev").disabled=page<=1;$("#pdf-next").disabled=page>=previewTotalPages;} $("#source-preview").showModal(); } catch(error){toast(error.message)} };
const loadSources = async () => { try { const result=await api("/knowledge/documents"); sourceDocuments=result.documents; renderSources(); await loadHealth(); await loadIngestionActivity(); } catch(error){toast(error.message)} };
const loadMetrics = async () => { try { const [snapshot,feedback]=await Promise.all([api("/metrics"),api("/knowledge/feedback/summary")]); const counters=snapshot.counters||{}; const durations=snapshot.durations||{}; const requests=Number(counters.assistant_requests_total||0); const verified=Number(counters.assistant_verified_total||0); $("#retrieval-count").textContent=Number(counters.retrieval_requests_total||0); $("#retrieval-results").textContent=Number(counters.retrieval_results_total||0); $("#verified-rate").textContent=requests?`${Math.round((verified/requests)*100)}%`:"0%"; $("#average-duration").textContent=durations.assistant_workflow_duration_ms?`${durations.assistant_workflow_duration_ms.average_ms} ms`:"—"; $("#feedback-rate").textContent=feedback.total?`${Math.round((feedback.helpful/feedback.total)*100)}%`:"—"; } catch(error){toast(error.message)} };
const loadLatencyHistory = async () => { try { const [history,summary]=await Promise.all([api("/knowledge/metrics/latency-history"),api("/knowledge/metrics/latency-summary")]); const max=Math.max(...history.map((item)=>item.duration_ms),1); $("#latency-chart").innerHTML=history.slice().reverse().map((item)=>`<span title="${Math.round(item.duration_ms)} ms · ${escapeHtml(item.profile)}" style="height:${Math.max(8,Math.round((item.duration_ms/max)*42))}px"></span>`).join(""); let summaryNode=$("#latency-summary"); if(!summaryNode){summaryNode=document.createElement("div");summaryNode.id="latency-summary";summaryNode.className="latency-summary";$("#latency-chart").before(summaryNode);} summaryNode.textContent=summary.sample_count?`Fast ${Math.round(summary.fastest_ms)} · Avg ${Math.round(summary.average_ms)} · p95 ${Math.round(summary.p95_ms)} · Slow ${Math.round(summary.slowest_ms)} ms`:"No samples yet"; let stages=$("#stage-latency"); if(!stages){stages=document.createElement("div");stages.id="stage-latency";stages.className="stage-latency";$("#latency-chart").after(stages);} stages.innerHTML=Object.entries(summary.stage_averages_ms||{}).map(([stage,value])=>`<span>${stage} ${Math.round(value)} ms</span>`).join(""); let recommendation=$("#latency-recommendation"); if(!recommendation){recommendation=document.createElement("div");recommendation.id="latency-recommendation";recommendation.className="latency-recommendation";$("#stage-latency").after(recommendation);} recommendation.textContent=summary.recommendation||""; } catch(error){toast(error.message)} };
const reindexDocument = async (path, button) => { button.disabled=true; button.textContent="…"; try { await api("/knowledge/index/file",{method:"POST",body:JSON.stringify({path})}); await loadSources(); toast("Document re-indexed successfully"); } catch(error){toast(error.message)} finally {button.disabled=false;button.textContent="↻";} };
const reindexStale = async () => { const button=$("#reindex-stale"); const status=$("#upload-status"); button.disabled=true; button.textContent="Indexing..."; status.textContent="Checking stale documents and rebuilding their knowledge..."; try { const result=await api("/knowledge/documents/reindex-stale",{method:"POST"}); await loadSources(); if(result.errors.length){status.textContent=`Completed with ${result.errors.length} error${result.errors.length===1?"":"s"}: ${result.errors.join(" · ")}`; toast("Some documents need attention");} else {status.textContent=result.reindexed_count?`Indexed: ${result.processed_documents.join(", ")}`:"All documents are already up to date."; toast(result.reindexed_count?`${result.reindexed_count} document${result.reindexed_count===1?"":"s"} re-indexed`:"No stale documents found");} } catch(error){status.textContent=`Indexing failed: ${error.message}`;toast(error.message)} finally {button.disabled=false;button.textContent="↻ Re-index stale";} };
const loadEvaluationHistory = async (dataset) => { const history=await api(`/knowledge/evaluation/history?dataset=${encodeURIComponent(dataset)}`); const percentage=(value)=>`${Math.round(value*100)}%`; const trend=(current,previous)=>{if(!previous||current===previous)return '<span class="trend-flat">→ 0</span>'; const change=Math.round((current-previous)*100); return `<span class="trend-${change>0?"up":"down"}">${change>0?"↑":"↓"} ${Math.abs(change)} pts</span>`;}; $("#quality-history").innerHTML=history.length?history.map((run,index)=>{const previous=history[index+1];return `<div class="history-row"><div><span>${new Date(`${run.created_at}Z`).toLocaleString()}</span><small>${run.dataset} · ${run.total_cases} cases</small></div><strong>${percentage(run.answerable_retrieval_rate)} retrieval ${trend(run.answerable_retrieval_rate,previous?.answerable_retrieval_rate)}<br>${percentage(run.answerable_citation_accuracy)} citations ${trend(run.answerable_citation_accuracy,previous?.answerable_citation_accuracy)}<br>${percentage(run.refusal_case_accuracy)} refusals ${trend(run.refusal_case_accuracy,previous?.refusal_case_accuracy)}</strong></div>`;}).join(""):'<span class="muted">No previous runs for this benchmark.</span>'; };
const runEvaluation = async () => { const button=$("#run-evaluation"); button.disabled=true; button.textContent="Running..."; try { const dataset=$("#evaluation-dataset").value; const report=await api("/knowledge/evaluation/run",{method:"POST",body:JSON.stringify({dataset})}); const percentage=(value)=>`${Math.round(value*100)}%`; const mark=(value)=>value?"✓ Pass":"× Review"; $("#quality-report").textContent=`${percentage(report.answer_match_rate)} answers · ${percentage(report.citation_accuracy)} citations`; $("#quality-summary").textContent=`${report.answerable_cases} answerable · ${report.refusal_cases} refusal cases · ${report.refusal_case_correct}/${report.refusal_cases} refusals correct`; $("#quality-metrics").innerHTML=[['Answerable retrieval',report.answerable_retrieval_rate],['Answerable citations',report.answerable_citation_accuracy],['Answer quality',report.answer_match_rate],['Refusal-case accuracy',report.refusal_case_accuracy]].map(([label,value])=>`<div class="quality-metric"><div><span>${label}</span><strong>${percentage(value)}</strong></div><div class="metric-track"><i style="width:${Math.round(value*100)}%"></i></div></div>`).join(""); $("#quality-categories").innerHTML=Object.entries(report.category_metrics||{}).map(([name,metrics])=>`<div class="quality-metric"><div><span>${escapeHtml(name.replaceAll("_"," "))} · ${metrics.cases} cases</span><strong>${percentage(metrics.answer_rate)} answers</strong></div><div class="metric-track"><i style="width:${Math.round(metrics.answer_rate*100)}%"></i></div><small class="category-detail">${percentage(metrics.retrieval_rate)} retrieval · ${metrics.refusal_cases?`${percentage(metrics.refusal_rate)} refusals`:`${percentage(metrics.answer_rate)} answer coverage`}</small></div>`).join(""); $("#quality-cases").innerHTML=report.cases.map((item)=>`<article class="quality-case"><div class="quality-case-top"><strong>${escapeHtml(item.question)}</strong><span class="case-status ${item.answer_match&&item.refusal_correct?"pass":"review"}">${item.answer_match&&item.refusal_correct?"PASS":"REVIEW"}</span></div><small>${escapeHtml(item.category.replaceAll("_"," "))} · Expected: ${escapeHtml(item.expected_source||"Refusal")}</small><small>Cited: ${escapeHtml(item.cited_sources.length?item.cited_sources.join(", "):"No source")}</small><div class="case-checks"><span>${mark(item.retrieval_hit)} retrieval</span><span>${mark(item.answer_match)} answer</span><span>${mark(item.citation_hit)} citation</span><span>${mark(item.refusal_correct)} refusal</span></div></article>`).join(""); await loadEvaluationHistory(dataset); $("#quality-preview").showModal(); toast("Quality check completed"); } catch(error){toast(error.message)} finally {button.disabled=false;button.textContent="Run quality check";} };
const compareProviders = async () => { const button=$("#compare-providers"); button.disabled=true; button.textContent="Comparing..."; try { const result=await api("/knowledge/evaluation/compare-providers",{method:"POST"}); const metrics=[['Answer quality','answer_match_rate'],['Retrieval','retrieval_hit_rate'],['Citations','citation_accuracy'],['Refusals','refusal_accuracy']]; $("#provider-summary").innerHTML=`<span class="comparison-status ${result.regression_detected?"regression":"healthy"}">${result.regression_detected?"Regression detected":"Quality thresholds passed"}</span><br>${escapeHtml(result.detail)}${result.regression_details.length?`<br>${result.regression_details.map(escapeHtml).join("<br>")}`:""}`; $("#provider-metrics").innerHTML=`<div class="provider-row provider-header"><strong>Metric</strong><strong>Deterministic</strong><strong>Ollama</strong></div>${metrics.map(([label,key])=>`<div class="provider-row"><span>${label}</span><strong>${Math.round(result.deterministic[key]*100)}%</strong><strong>${result.ollama?`${Math.round(result.ollama[key]*100)}%`:"Unavailable"}</strong></div>`).join("")}`; $("#provider-preview").showModal(); } catch(error){toast(error.message)} finally {button.disabled=false;button.textContent="Compare providers";} };
const deleteDocument = async (name) => { if(!window.confirm(`Delete ${name} and remove its indexed knowledge?`)) return; try { await api(`/knowledge/documents/${encodeURIComponent(name)}`,{method:"DELETE"}); await loadSources(); toast("Document deleted"); } catch(error){toast(error.message)} };
const uploadDocument = async (file) => { const status=$("#upload-status"); status.textContent=`Validating ${file.name}...`; try { const allowed=[".pdf",".md",".markdown",".txt"]; if(!allowed.some((extension)=>file.name.toLowerCase().endsWith(extension))){throw new Error("Unsupported file type. Upload PDF, Markdown, or text files.")} status.textContent=`Uploading and indexing ${file.name}...`; const form=new FormData(); form.append("file",file); const response=await fetch("/knowledge/documents/upload",{method:"POST",body:form}); if(!response.ok){const body=await response.json().catch(()=>({detail:"Upload failed"}));throw new Error(body.detail||"Upload failed")} const saved=await response.json(); status.textContent=`Indexed ${saved.name} successfully.`; await loadSources(); toast("Document uploaded and indexed"); } catch(error){status.textContent=`Upload not completed: ${error.message}`;toast(error.message)} finally {$("#file-upload").value="";} };
const loadConversations = async () => { try { const result=await api("/knowledge/conversations"); const conversations=await Promise.all(result.conversation_ids.slice().reverse().map(async (id)=>({id,history:await api(`/knowledge/conversations/${id}`)}))); const list=$("#conversation-list"); list.innerHTML=""; if(!conversations.length){list.innerHTML='<span class="muted">No conversations yet.</span>';return;} conversations.forEach(({id,history},index)=>{const row=document.createElement("div"); row.className="conversation-row"; const item=document.createElement("button"); item.className=`conversation-item ${id===conversationId?"active":""}`; item.dataset.conversationId=id; const title=document.createElement("span"); title.className="conversation-title"; title.textContent=history.turns[0]?.question||`Conversation ${conversations.length-index}`; const meta=document.createElement("span"); meta.className="conversation-meta"; meta.textContent=`${history.turns.length} turn${history.turns.length===1?"":"s"}`; item.append(title,meta); item.addEventListener("click",()=>loadConversation(id)); const remove=document.createElement("button"); remove.className="conversation-delete"; remove.type="button"; remove.title="Delete conversation"; remove.setAttribute("aria-label","Delete conversation"); remove.textContent="×"; remove.addEventListener("click",(event)=>{event.stopPropagation();deleteConversation(id)}); row.append(item,remove); list.appendChild(row);}); } catch(error){toast(error.message)} };
const deleteConversation = async (id) => { if(!window.confirm("Delete this conversation?")) return; try { await api(`/knowledge/conversations/${id}`,{method:"DELETE"}); if(conversationId===id){conversationId=null;$("#result-section").classList.add("hidden");} await loadConversations(); toast("Conversation deleted"); } catch(error){toast(error.message)} };
const loadConversation = async (id) => { try { const result=await api(`/knowledge/conversations/${id}`); conversationId=id; const latest=result.turns[result.turns.length-1]; if(latest){$("#result-section").classList.remove("hidden"); $("#answer-loader").classList.add("hidden"); $("#answer-content").classList.remove("hidden"); $("#answer").textContent=latest.answer; $("#result-meta").textContent=`Conversation history · ${result.turns.length} turn${result.turns.length===1?"":"s"}`; $("#source-count").textContent="Saved response"; $("#sources").innerHTML="<div class=\"empty-state\">Sources are shown when you ask a new question.</div>"; } await loadConversations(); } catch(error){toast(error.message)} };
const startNewConversation = () => { conversationId=null; $("#question").value=""; $("#question").focus(); document.querySelectorAll(".conversation-item").forEach((item)=>item.classList.remove("active")); toast("New conversation started"); };
