const downloadEvaluation = (format) => { if(!lastEvaluationReport)return; const report=lastEvaluationReport; const headers=["question","category","expected_source","cited_sources","retrieval_hit","answer_match","citation_hit","refusal_correct"]; let content; let mime; let extension; if(format==="json"){content=JSON.stringify(report,null,2);mime="application/json";extension="json";}else{const rows=report.cases.map((item)=>headers.map((header)=>`"${String(header==="cited_sources"?item[header].join("; "):item[header]??"").replaceAll('"','""')}"`).join(",")); content=[headers.join(","),...rows].join("\n");mime="text/csv";extension="csv";} const link=document.createElement("a"); link.href=URL.createObjectURL(new Blob([content],{type:mime})); link.download=`atlas-quality-report-${new Date().toISOString().slice(0,10)}.${extension}`; link.click(); URL.revokeObjectURL(link.href); toast(`Downloaded ${extension.toUpperCase()} report`); };
